css:
.ss-gl{border:1px solid var(--line);border-top:4px solid var(--accent);padding:30px 28px}
.ss-gl__t{font:700 11px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:var(--accent);margin-bottom:20px}
.ss-gl__rows{display:flex;flex-direction:column}
.ss-gl__r{display:grid;grid-template-columns:190px 1fr;gap:20px;padding:12px 0;border-bottom:1px solid var(--line)}
.ss-gl__l{font:700 10px/1.6 var(--font-body);letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.ss-gl__v{font-size:15px;line-height:1.65;color:var(--ink)}
@media (max-width:640px){.ss-gl__r{grid-template-columns:1fr;gap:4px}}
@media (max-width:640px){.ss-gl__l{font-size:12px}}
